#!/bin/sh
# Generated by FWShift: OCI network security groups for one VCN, created with the OCI CLI. Read the report
# first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                                   prints the calls, makes none (no OCI access needed)
#   COMPARTMENT_ID=ocid1.compartment... VCN_ID=ocid1.vcn... sh THIS_FILE
#                                                            creates the NSGs and their rules
#
# OCI_OPTS adds options to every call, for example OCI_OPTS='--profile PROD --region eu-frankfurt-1'.
#
# The NSGs are created WITHOUT VNICs: nothing changes for any traffic until VNICs are put in them. Put each VNIC
# in every NSG whose list (# attach ...) holds one of its addresses, and in no other. The security lists of the
# subnets keep applying: OCI allows what a rule of either allows. An NSG of the same name in the VCN stops the
# script before anything is created; a call OCI refuses stops it where it is (delete the NSGs it made with
# oci network nsg delete --nsg-id ... --force, and run it again). Every rule is stateful.
set -u
DRY_RUN="${DRY_RUN:-}"
OCI_OPTS="${OCI_OPTS:-}"
if [ -z "$DRY_RUN" ]; then
  : "${COMPARTMENT_ID:?set COMPARTMENT_ID to the OCID of the compartment for the NSGs, or DRY_RUN=1 to print the calls}"
  : "${VCN_ID:?set VCN_ID to the OCID of the VCN, or DRY_RUN=1 to print the calls}"
else
  COMPARTMENT_ID="${COMPARTMENT_ID:-ocid1.compartment.oc1..dryrun}"
  VCN_ID="${VCN_ID:-ocid1.vcn.oc1..dryrun}"
fi
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
show() { printf 'oci' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; }
# free NAME: stops the script when the VCN has an NSG of that name that is not terminated
free() {
  if [ -n "$DRY_RUN" ]; then return 0; fi
  found=$(oci network nsg list --compartment-id "$COMPARTMENT_ID" --vcn-id "$VCN_ID" --display-name "$1" --all --query "length(data[?\"lifecycle-state\" != 'TERMINATED'])" --raw-output $OCI_OPTS) || fail "nsg list: $found"
  case "$found" in ""|0) return 0 ;; esac
  fail "an NSG named $1 exists in $VCN_ID already; nothing was created"
}
# nsg NAME: creates an NSG without rules and prints its OCID
nsg() {
  if [ -n "$DRY_RUN" ]; then show network nsg create --compartment-id "$COMPARTMENT_ID" --vcn-id "$VCN_ID" --display-name "$1"; printf 'ocid1.networksecuritygroup.dryrun.%s\n' "$1"; return 0; fi
  id=$(oci network nsg create --compartment-id "$COMPARTMENT_ID" --vcn-id "$VCN_ID" --display-name "$1" --freeform-tags '{"fwshift":"generated"}' --wait-for-state AVAILABLE --query data.id --raw-output $OCI_OPTS) || fail "nsg create $1"
  case "$id" in ocid1.networksecuritygroup.*) ;; *) fail "nsg create $1: no OCID in the answer" ;; esac
  printf 'created %s %s\n' "$1" "$id" >&2
  printf '%s\n' "$id"
}
# rules NSG: adds the rules on standard input, a JSON list of at most 25 (AddSecurityRuleDetails)
rules() {
  json=$(cat)
  if [ -n "$DRY_RUN" ]; then show network nsg rules add --nsg-id "$1" --security-rules "$json"; return 0; fi
  oci network nsg rules add --nsg-id "$1" --security-rules "$json" $OCI_OPTS >/dev/null || fail "nsg rules add $1"
}

# No NSG of these names may exist.
free 'fwshift-addresses-ipv6'
free 'fwshift-lan6-ipv6'
free 'fwshift-partners-ipv6-ipv6'
free 'fwshift-no-rules'

# The NSGs, each with the addresses of the VNICs it is for.
# attach fwshift-addresses-ipv6: ::-2001:db8:f:ffff:ffff:ffff:ffff:ffff 2001:db8:10:1::-2001:db8:98:ffff:ffff:ffff:ffff:ffff 2001:db8:9a::-ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff
G1=$(nsg 'fwshift-addresses-ipv6') || exit 1
# attach fwshift-lan6-ipv6: 2001:db8:10::/64
G2=$(nsg 'fwshift-lan6-ipv6') || exit 1
# attach fwshift-partners-ipv6-ipv6: 2001:db8:99::/48
G3=$(nsg 'fwshift-partners-ipv6-ipv6') || exit 1
# attach fwshift-no-rules: 0.0.0.0/0
G4=$(nsg 'fwshift-no-rules') || exit 1

# Their rules: ingress rules name the sources, egress rules the destinations.
rules "$G1" <<'FWSHIFT_JSON'
[{"description": "FWShift: ICMPv6 echo", "direction": "INGRESS", "icmpOptions": {"type": 128}, "isStateless": false, "protocol": "58", "source": "::/0", "sourceType": "CIDR_BLOCK"}, {"description": "FWShift: ICMPv6 echo", "destination": "::/0", "destinationType": "CIDR_BLOCK", "direction": "EGRESS", "icmpOptions": {"type": 128}, "isStateless": false, "protocol": "58"}]
FWSHIFT_JSON
rules "$G2" <<'FWSHIFT_JSON'
[{"description": "FWShift: the partners reach the web servers of the LAN by HTTPS and nothing else", "direction": "INGRESS", "isStateless": false, "protocol": "6", "source": "2001:db8:99::/48", "sourceType": "CIDR_BLOCK", "tcpOptions": {"destinationPortRange": {"max": 443, "min": 443}}}, {"description": "FWShift: ICMPv6 echo", "direction": "INGRESS", "icmpOptions": {"type": 128}, "isStateless": false, "protocol": "58", "source": "::/0", "sourceType": "CIDR_BLOCK"}, {"description": "FWShift: ICMPv6 echo", "destination": "::/0", "destinationType": "CIDR_BLOCK", "direction": "EGRESS", "icmpOptions": {"type": 128}, "isStateless": false, "protocol": "58"}]
FWSHIFT_JSON
rules "$G3" <<'FWSHIFT_JSON'
[{"description": "FWShift: ICMPv6 echo", "direction": "INGRESS", "icmpOptions": {"type": 128}, "isStateless": false, "protocol": "58", "source": "::/0", "sourceType": "CIDR_BLOCK"}, {"description": "FWShift: the partners reach the web servers of the LAN by HTTPS and nothing else", "destination": "2001:db8:10::/64", "destinationType": "CIDR_BLOCK", "direction": "EGRESS", "isStateless": false, "protocol": "6", "tcpOptions": {"destinationPortRange": {"max": 443, "min": 443}}}, {"description": "FWShift: ICMPv6 echo", "destination": "::/0", "destinationType": "CIDR_BLOCK", "direction": "EGRESS", "icmpOptions": {"type": 128}, "isStateless": false, "protocol": "58"}]
FWSHIFT_JSON

# Not written:
#   rule defconf: accept in ipsec policy: not written, see the report
#   rule banned scanners: not written, see the report
#   rule ssh from the admins: not written, see the report
#   rule web for everyone: not written, see the report
#   rule web for everyone-2: not written, see the report
#   rule ping "echo" only: not written, see the report
#   rule ping "echo" only-2: not written, see the report
#   rule old partner access: disabled in the source, not written
#   rule old partner access-2: disabled in the source, not written
#   rule rest of the DMZ: not written, see the report
#   rule rest of the DMZ-2: not written, see the report
#   rule rest of the DMZ-3: not written, see the report
#   rule LAN to the package mirrors: not written, see the report
#   rule guest DNS, either port: not written, see the report
#   rule guest DNS, either port-2: not written, see the report
#   rule guests to the internet: not written, see the report
#   rule office hours for staff: not written, see the report
#   rule defconf: drop all from WAN not DSTNATed (allows publish web): not written, see the report
#   rule defconf: drop all from WAN not DSTNATed (allows publish mail): not written, see the report

echo 'Done. Put the VNICs in the NSGs the comments above name; until then nothing changes.' >&2
